    "source": "# NAFv4.1 pp.109–110: nine elements and nine directed relationships.\n# Geographic Location is one conceptual parameter shared by both operations.\n# Resource deliberately has no physical-resource trace, as in the example.\narchitecture \"NAFv4.1 · S7 Service Interface Parameters\" {\n  config { profile naf41-uaf views all }\n  model {\n    Service situation \"Situation Information Consolidation\"\n    ServiceInterface picture \"Situation Picture\"\n    ServiceOperation submitLocation \"submit Location Of Resource\"\n    ServiceOperation setArea \"set Area Of Interest\"\n    ServiceOperationParameter geographicLocation \"Geographic Location\"\n    ServiceOperationParameter resource \"Resource\" {resource positionReport}\n    ServiceOperationParameter track \"Track\"\n    DataProductType positionReport \"Position Report\"\n    DataProductType targetTrackRecord \"Target Track Record\"\n\n    relation specifiesInterface situation -> picture \"specifies\" { type SpecifiesServiceInterface }\n    relation specifiesSubmit picture -> submitLocation \"specifies\" { type SpecifiesServiceOperation }\n    relation specifiesArea picture -> setArea \"specifies\" { type SpecifiesServiceOperation }\n    relation submitGeography submitLocation -> geographicLocation \"has\" { type HasServiceOperationParameter }\n    relation areaGeography setArea -> geographicLocation \"has\" { type HasServiceOperationParameter }\n    relation submitResource submitLocation -> resource \"has\" { type HasServiceOperationParameter }\n    relation submitTrack submitLocation -> track \"has\" { type HasServiceOperationParameter }\n    relation geographyProduct geographicLocation -> positionReport \"involves\" { type InvolvesPhysicalResource }\n    relation trackProduct track -> targetTrackRecord \"involves\" { type InvolvesPhysicalResource }\n    ServiceFunction receiving \"Data Receiving\"\n    ServiceFunction storing \"Data Storing\"\n    ServiceFunctionParameter incoming \"Incoming data\"\n    ServiceFunctionParameter payload \"Data Payload\"\n    InformationProduct report \"Situational Report\"\n    InformationProduct pictureProduct \"Consolidated Situational Picture\"\n    relation receivingEnables receiving -> situation \"enables\" {type EnablesService}\n    relation storingEnables storing -> situation \"enables\" {type EnablesService}\n    relation receivingParameter receiving -> incoming \"has\" {type HasServiceFunctionParameter}\n    relation storingParameter storing -> payload \"has\" {type HasServiceFunctionParameter}\n    relation incomingProduct incoming -> report \"involves\" {type InvolvesLogicalResource}\n    relation payloadProduct payload -> pictureProduct \"involves\" {type InvolvesLogicalResource}\n  }\n  view s3 \"S3 · Service Interfaces\" {\n    viewpoint S3\n    include situation,picture,submitLocation,setArea,geographicLocation,resource,track,positionReport,targetTrackRecord\n    place situation at (110,0)\n    style situation { width 300 }\n    place picture at (0,240)\n    style picture { width 520 }\n    place submitLocation at (0,500)\n    place setArea at (400,500)\n    style submitLocation { width 300 }\n    style setArea { width 300 }\n    place geographicLocation at (800,740)\n    place resource at (geographicLocation.x,1000)\n    place track at (geographicLocation.x,1260)\n    style geographicLocation { width 300 }\n    style resource { width 300 }\n    style track { width 300 }\n    place positionReport at (1240,geographicLocation.y)\n    place targetTrackRecord at (1240,track.y)\n    style positionReport { width 300 }\n    style targetTrackRecord { width 300 }\n    routes { curve orthogonal }\n    route specifiesInterface { from bottom to top }\n    route specifiesSubmit { from bottom to top via (picture.centerX,picture.bottom+80),(submitLocation.centerX,picture.bottom+80) }\n    route specifiesArea { from bottom to top via (picture.centerX,picture.bottom+80),(setArea.centerX,picture.bottom+80) }\n    route submitGeography { from bottom 1/2 to left 3/4 via (submitLocation.centerX,geographicLocation.y+geographicLocation.height*3/4) }\n    route areaGeography { from bottom 1/2 to left 1/4 via (setArea.centerX,geographicLocation.y+geographicLocation.height/4) }\n    route submitResource { from bottom to left via (submitLocation.centerX,resource.centerY) }\n    route submitTrack { from bottom to left via (submitLocation.centerX,track.centerY) }\n    route geographyProduct { from right to left }\n    route trackProduct { from right to left }\n  }\n  view s7 \"S7 · Extended operation parameters\" {\n    extends s3\n    viewpoint S7\n    include receiving,storing,incoming,payload,report,pictureProduct\n    place receiving at (submitLocation.x,track.bottom+180)\n    place storing at (receiving.x,receiving.bottom+180)\n    place incoming at (geographicLocation.x,receiving.y)\n    place payload at (incoming.x,storing.y)\n    place report at (positionReport.x,incoming.y)\n    place pictureProduct at (report.x,payload.y)\n    place situation at (-400,240)\n    style receiving {width 300}\n    style storing {width 300}\n    style incoming {width 300}\n    style payload {width 300}\n    style report {width 300}\n    style pictureProduct {width 300}\n    route specifiesInterface {from right to left curve straight}\n    route receivingEnables {from left to bottom via (situation.centerX,receiving.centerY)}\n    route storingEnables {from left to bottom via (situation.centerX,storing.centerY)}\n  }\n  view embeddedS7 \"S7 · Embedded S3\" {\n    viewpoint S7\n    include receiving,storing,incoming,payload,report,pictureProduct\n    embed s3 as interfaces {frame true}\n    place receiving at (interfaces.x,interfaces.bottom+120)\n    place storing at (receiving.x,receiving.bottom+120)\n    place incoming at (receiving.right+120,receiving.y)\n    place payload at (incoming.x,storing.y)\n    place report at (incoming.right+120,incoming.y)\n    place pictureProduct at (report.x,payload.y)\n    place interfaces at (0,0)\n  }\n}\n"
