    "source": "architecture \"Three icon libraries\" {\n  description \"The same architecture vocabulary, illustrated with Bootstrap, Lucide, and Tabler.\"\n  model {\n    package bootstrap \"Bootstrap Icons\" {\n      person bi_user \"Customer\" { icon bootstrap.person technology \"bootstrap.person\" }\n      application bi_app \"Application\" { icon bootstrap.window technology \"bootstrap.window\" }\n      database bi_data \"Database\" { icon bootstrap.database technology \"bootstrap.database\" }\n      service bi_cloud \"Cloud service\" { icon bootstrap.cloud technology \"bootstrap.cloud\" }\n    }\n    package lucide \"Lucide\" {\n      person lu_user \"Customer\" { icon lucide.user technology \"lucide.user\" }\n      application lu_app \"Application\" { icon lucide.app-window technology \"lucide.app-window\" }\n      database lu_data \"Database\" { icon lucide.database technology \"lucide.database\" }\n      service lu_cloud \"Cloud service\" { icon lucide.cloud technology \"lucide.cloud\" }\n    }\n    package tabler \"Tabler Icons\" {\n      person ta_user \"Customer\" { icon tabler.user technology \"tabler.user\" }\n      application ta_app \"Application\" { icon tabler.app-window technology \"tabler.app-window\" }\n      database ta_data \"Database\" { icon tabler.database technology \"tabler.database\" }\n      service ta_cloud \"Cloud service\" { icon tabler.cloud technology \"tabler.cloud\" }\n    }\n  }\n  view compare \"Iconpack comparison\" {\n    place bootstrap at (0, 0)\n    place lucide at (0, 260)\n    place tabler at (0, 520)\n    place bi_user at (0, 0)\n    place bi_app at (260, 0)\n    place bi_data at (520, 0)\n    place bi_cloud at (780, 0)\n    place lu_user at (0, 0)\n    place lu_app at (260, 0)\n    place lu_data at (520, 0)\n    place lu_cloud at (780, 0)\n    place ta_user at (0, 0)\n    place ta_app at (260, 0)\n    place ta_data at (520, 0)\n    place ta_cloud at (780, 0)\n    style bootstrap { icon bootstrap.bootstrap accent \"#7952b3\" }\n    style lucide { icon lucide.feather accent \"#ef4444\" }\n    style tabler { icon tabler.brand-tabler accent \"#206bc4\" }\n  }\n  view bootstrap_detail \"Bootstrap detail\" { include bootstrap }\n  view lucide_detail \"Lucide detail\" { include lucide }\n  view tabler_detail \"Tabler detail\" { include tabler }\n}\n"
